package com.cappleapple.astralrepository.platform.fluids;
public final class FluidUtil {public static java.util.Optional<FluidStack> getFluidContained(net.minecraft.world.item.ItemStack stack){var storage=net.fabricmc.fabric.api.transfer.v1.context.ContainerItemContext.withConstant(stack).find(net.fabricmc.fabric.api.transfer.v1.fluid.FluidStorage.ITEM);if(storage==null)return java.util.Optional.empty();for(var view:storage)if(!view.isResourceBlank()&&view.getAmount()>=81)return java.util.Optional.of(new FluidStack(view.getResource(),(int)Math.min(Integer.MAX_VALUE,view.getAmount()/81)));return java.util.Optional.empty();}}
